class Solution {
  private static long gcd(long a, long b) {
    while (b != 0) {
      long t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  private static int digitsNeeded(long r) {
    int c = 0;
    for (int d = 9; d >= 2; d--) {
      while (r % d == 0) {
        r /= d;
        c++;
      }
    }
    return c;
  }

  private static void appendDigits(StringBuilder sb, long r, int ones) {
    for (int i = 0; i < ones; i++) sb.append('1');
    StringBuilder rev = new StringBuilder();
    for (int d = 9; d >= 2; d--) {
      while (r % d == 0) {
        r /= d;
        rev.append((char) ('0' + d));
      }
    }
    sb.append(rev.reverse());
  }

  public String smallestNumber(String num, long t) {
    long tt = t;
    for (int p : new int[] {2, 3, 5, 7}) while (tt % p == 0) tt /= p;
    if (tt != 1) return "-1";
    int n = num.length();
    int z = num.indexOf('0');
    if (z < 0) z = n;
    long[] rem = new long[Math.min(z, n) + 1];
    rem[0] = t;
    for (int i = 0; i < z && i < n; i++) {
      rem[i + 1] = rem[i] / gcd(rem[i], num.charAt(i) - '0');
    }
    if (z == n && rem[n] == 1) return num;
    for (int i = Math.min(n - 1, z); i >= 0; i--) {
      for (int d = num.charAt(i) - '0' + 1; d <= 9; d++) {
        long r = rem[i] / gcd(rem[i], d);
        int need = digitsNeeded(r), len = n - i - 1;
        if (need <= len) {
          StringBuilder sb = new StringBuilder(n + 1);
          sb.append(num, 0, i).append((char) ('0' + d));
          appendDigits(sb, r, len - need);
          return sb.toString();
        }
      }
    }
    int m = digitsNeeded(t);
    StringBuilder sb = new StringBuilder();
    appendDigits(sb, t, Math.max(m, n + 1) - m);
    return sb.toString();
  }
}
